    result = {}
    for key, value in d.items():
        if isinstance(value, dict) and value:
            sub_dict = flatten_dict(value, sep=sep)
            for sub_key, sub_value in sub_dict.items():
                result[f"{key}{sep}{sub_key}"] = sub_value
