def top_k(words, k):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return []
    if k >= len(counts):
        return sorted(counts.values(), reverse=True)
    return sorted(counts.items(), key=lambda x: (-x[1], x[0]))[:k]

